#!/usr/bin/env node
'use strict';
// Builds preload.bundle.js: Oto's window preload (preload.js) plus the extension toolbar module
// (electron-chrome-extensions/browser-action) in ONE file.
// Why: Oto's windows run sandboxed (since 1.3.3), and a sandboxed preload can only require('electron'), not other
// files. The toolbar module only uses contextBridge, ipcRenderer, webFrame and process.contextIsolated, which all
// work in the sandbox. No extra tools: the module is wrapped as a CommonJS function.
// Runs from npm start / pack / dist; the tests fail if the committed bundle is out of date (e.g. after Dependabot
// updates the extension library). Usage: node scripts/build-preload.js [--check]
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
function build() {
  const pre = fs.readFileSync(path.join(ROOT, 'preload.js'), 'utf8');
  const baFile = require.resolve('electron-chrome-extensions/browser-action', { paths: [ROOT] });
  const ba = fs.readFileSync(baFile, 'utf8').replace(/\n\/\/# sourceMappingURL=.*\s*$/, '\n');
  const ver = JSON.parse(fs.readFileSync(path.join(path.dirname(baFile), '..', '..', 'package.json'), 'utf8')).version;
  const call = "require('electron-chrome-extensions/browser-action')";
  if (!pre.includes(call)) throw new Error(`preload.js no longer contains ${call}`);
  if (/require\((?!["']electron["']\))/.test(ba)) throw new Error('the toolbar module now requires something besides electron; it would not work sandboxed');
  return [
    '// GENERATED by scripts/build-preload.js. Do not edit; edit preload.js and run `node scripts/build-preload.js`.',
    `// Contains preload.js + electron-chrome-extensions@${ver}/browser-action (MIT), so it can run in a sandboxed preload.`,
    "'use strict';",
    'const __otoBrowserAction = (() => {',
    '  const module = { exports: {} };',
    '  (function (module, exports, require) {',
    ba.trimEnd(),
    '  })(module, module.exports, require);',
    '  return module.exports;',
    '})();',
    '',
    pre.replace(/^'use strict';\n/m, '').replace(call, '__otoBrowserAction'),
  ].join('\n');
}
module.exports = { build };
if (require.main === module) {
  const out = path.join(ROOT, 'preload.bundle.js');
  const next = build();
  if (process.argv.includes('--check')) {
    const cur = fs.existsSync(out) ? fs.readFileSync(out, 'utf8') : '';
    if (cur !== next) { console.error('preload.bundle.js is out of date: run node scripts/build-preload.js'); process.exit(1); }
    console.log('preload.bundle.js is up to date');
  } else { fs.writeFileSync(out, next); console.log('wrote preload.bundle.js'); }
}
